//! Simple reader for the JSON reference cases generated by PySCF.
//!
//! The structs below intentionally mirror `testdata/reference/cases/*.json`.
//! Keep this module boring: tests can load a case and compare library output
//! directly against the slices in `TestCase`.

const std = @import("std");
const basis = @import("basis.zig");
const gaussian_orbital = @import("gaussian_orbital.zig");
const types = @import("types.zig");

pub const Matrix = [][]f64;
pub const Vector = []f64;
pub const EriTensor = [][][][]f64;
pub const MolecularCharge = types.MolecularCharge;
pub const MolecularSpin = types.MolecularSpin;

pub const angstrom_per_bohr: f64 = 0.529177210903;

pub const UnitError = error{UnsupportedUnit};
pub const ElementError = error{UnsupportedElement};
pub const BuildShellsError = ElementError || UnitError || basis.ShellsForAtomError;

pub fn toBohr(point: [3]f64, unit: []const u8) UnitError![3]f64 {
    if (std.mem.eql(u8, unit, "bohr")) return point;
    if (std.mem.eql(u8, unit, "angstrom")) {
        return .{
            point[0] / angstrom_per_bohr,
            point[1] / angstrom_per_bohr,
            point[2] / angstrom_per_bohr,
        };
    }
    return error.UnsupportedUnit;
}

/// Atomic-number lookup for the small element set the library currently uses.
/// Z = 0..20 (X, H..Ca). Will grow as heavier elements come into scope.
pub fn atomicNumberForSymbol(symbol: []const u8) ElementError!types.AtomicNumber {
    const symbols = [_][]const u8{
        "X",  "H",  "He", "Li", "Be", "B", "C",  "N",  "O", "F",  "Ne",
        "Na", "Mg", "Al", "Si", "P",  "S", "Cl", "Ar", "K", "Ca",
    };

    for (symbols, 0..) |candidate, atomic_number| {
        if (std.mem.eql(u8, symbol, candidate)) return @intCast(atomic_number);
    }
    return error.UnsupportedElement;
}

pub const Atom = struct {
    symbol: []const u8,
    coord: [3]f64,

    /// JSON shape: ["H", [x, y, z]]
    pub fn jsonParse(
        allocator: std.mem.Allocator,
        source: anytype,
        options: std.json.ParseOptions,
    ) !Atom {
        if (try source.next() != .array_begin) return error.UnexpectedToken;
        const symbol = try std.json.innerParse([]const u8, allocator, source, options);
        const coord = try std.json.innerParse([3]f64, allocator, source, options);
        if (try source.next() != .array_end) return error.UnexpectedToken;
        return .{ .symbol = symbol, .coord = coord };
    }
};

pub const Molecule = struct {
    atoms: []Atom,
    unit: []const u8,
    charge: MolecularCharge,
    spin: MolecularSpin,

    /// Builds the shell list for this molecule against `basis_set`.
    /// Caller owns the returned slice; primitive slices stay borrowed
    /// from `basis_set` and remain valid for the basis set's lifetime.
    pub fn buildShells(
        self: Molecule,
        comptime T: type,
        allocator: std.mem.Allocator,
        basis_set: basis.BasisSet(T),
    ) BuildShellsError![]gaussian_orbital.Shell(T) {
        const Shell = gaussian_orbital.Shell(T);
        var shells: std.ArrayList(Shell) = .empty;
        errdefer shells.deinit(allocator);

        for (self.atoms) |atom| {
            const atomic_number = try atomicNumberForSymbol(atom.symbol);
            const center_f64 = try toBohr(atom.coord, self.unit);
            const center: [3]T = .{
                @floatCast(center_f64[0]),
                @floatCast(center_f64[1]),
                @floatCast(center_f64[2]),
            };
            const atom_shells = try basis_set.shellsForAtom(allocator, atomic_number, center);
            defer allocator.free(atom_shells);
            try shells.appendSlice(allocator, atom_shells);
        }

        return shells.toOwnedSlice(allocator);
    }
};

pub const ScfResult = struct {
    method: []const u8,
    converged: bool,
    energy: f64,
    density: Matrix,
    mo_energies: Vector,
};

pub const AoLabel = struct {
    index: usize,
    atom_index: usize,
    atom_symbol: []const u8,
    shell: []const u8,
    component: []const u8,
    name: []const u8,
};

pub const TestCase = struct {
    case: []const u8,
    molecule: Molecule,
    basis: []const u8,
    nao: usize,
    natm: usize,
    nelectron: usize,
    nuclear_repulsion: f64,
    pyscf_version: []const u8,
    ao_labels: []AoLabel,
    S: Matrix,
    T: Matrix,
    V_nuc: Matrix,
    eri: ?EriTensor = null,
    scf: ?ScfResult = null,
};

pub const ParsedTestCase = std.json.Parsed(TestCase);

pub const TestCases = struct {
    items: []ParsedTestCase,

    pub fn deinit(self: *TestCases, allocator: std.mem.Allocator) void {
        for (self.items) |parsed| parsed.deinit();
        allocator.free(self.items);
        self.* = undefined;
    }

    pub fn get(self: *const TestCases, name: []const u8) ?*const TestCase {
        for (self.items) |*parsed| {
            if (std.mem.eql(u8, parsed.value.case, name)) return &parsed.value;
        }
        return null;
    }
};

pub fn parseTestCase(allocator: std.mem.Allocator, json_text: []const u8) !ParsedTestCase {
    // `.alloc_always` duplicates every string in the JSON into the
    // arena, so the returned `Parsed` value is self-contained and the
    // source buffer can be freed immediately. Trades a one-shot
    // allocation cost for a simpler lifetime contract — fine for
    // fixture loading.
    return std.json.parseFromSlice(
        TestCase,
        allocator,
        json_text,
        .{ .ignore_unknown_fields = true, .allocate = .alloc_always },
    );
}

pub fn readTestCaseFile(
    io: std.Io,
    allocator: std.mem.Allocator,
    path: []const u8,
) !ParsedTestCase {
    const json_text = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited);
    defer allocator.free(json_text);
    return parseTestCase(allocator, json_text);
}

pub fn readTestCasesDir(
    io: std.Io,
    allocator: std.mem.Allocator,
    dir_path: []const u8,
) !TestCases {
    var dir = try std.Io.Dir.cwd().openDir(io, dir_path, .{ .iterate = true });
    defer dir.close(io);

    var parsed_cases: std.ArrayList(ParsedTestCase) = .empty;
    errdefer {
        for (parsed_cases.items) |parsed| parsed.deinit();
        parsed_cases.deinit(allocator);
    }

    var it = dir.iterate();
    while (try it.next(io)) |entry| {
        if (entry.kind != .file) continue;
        if (!std.mem.endsWith(u8, entry.name, ".json")) continue;

        const json_text = try dir.readFileAlloc(io, entry.name, allocator, .unlimited);
        defer allocator.free(json_text);

        const parsed = try parseTestCase(allocator, json_text);
        errdefer parsed.deinit();
        try parsed_cases.append(allocator, parsed);
    }

    const items = try parsed_cases.toOwnedSlice(allocator);
    std.mem.sort(ParsedTestCase, items, {}, parsedTestCaseLessThan);
    return .{ .items = items };
}

fn parsedTestCaseLessThan(_: void, lhs: ParsedTestCase, rhs: ParsedTestCase) bool {
    return std.mem.lessThan(u8, lhs.value.case, rhs.value.case);
}

pub const ShapeError = error{ShapeMismatch};

pub fn validateShapes(case: TestCase) ShapeError!void {
    if (case.molecule.atoms.len != case.natm) return error.ShapeMismatch;
    if (case.ao_labels.len != case.nao) return error.ShapeMismatch;
    for (case.ao_labels, 0..) |label, i| {
        if (label.index != i) return error.ShapeMismatch;
        if (label.atom_index >= case.natm) return error.ShapeMismatch;
        if (label.atom_index >= case.molecule.atoms.len) return error.ShapeMismatch;
        if (!std.mem.eql(u8, label.atom_symbol, case.molecule.atoms[label.atom_index].symbol)) {
            return error.ShapeMismatch;
        }
    }

    try validateMatrix(case.S, case.nao, case.nao);
    try validateMatrix(case.T, case.nao, case.nao);
    try validateMatrix(case.V_nuc, case.nao, case.nao);

    if (case.eri) |eri| {
        if (eri.len != case.nao) return error.ShapeMismatch;
        for (eri) |a| {
            if (a.len != case.nao) return error.ShapeMismatch;
            for (a) |b| {
                if (b.len != case.nao) return error.ShapeMismatch;
                for (b) |c| {
                    if (c.len != case.nao) return error.ShapeMismatch;
                }
            }
        }
    }

    if (case.scf) |scf| {
        try validateMatrix(scf.density, case.nao, case.nao);
        if (scf.mo_energies.len != case.nao) return error.ShapeMismatch;
    }
}

fn validateMatrix(matrix: Matrix, rows: usize, cols: usize) ShapeError!void {
    if (matrix.len != rows) return error.ShapeMismatch;
    for (matrix) |row| {
        if (row.len != cols) return error.ShapeMismatch;
    }
}

const integral_tolerance = 1e-8;

fn readFixture(path: []const u8) !ParsedTestCase {
    return readTestCaseFile(std.testing.io, std.testing.allocator, path);
}

fn expectIntegral(expected: f64, actual: f64) !void {
    try std.testing.expectApproxEqAbs(expected, actual, integral_tolerance);
}

test "parseTestCase reads inline json into the plain data structure" {
    const text =
        \\{
        \\  "case": "test",
        \\  "molecule": {
        \\    "atoms": [["H", [0.0, 0.0, 0.0]], ["H", [0.0, 0.0, 0.74]]],
        \\    "unit": "angstrom", "charge": 0, "spin": 0
        \\  },
        \\  "basis": "sto-3g",
        \\  "nao": 2, "natm": 2, "nelectron": 2,
        \\  "nuclear_repulsion": 0.7146,
        \\  "pyscf_version": "test",
        \\  "ao_labels": [
        \\    {"index":0,"atom_index":0,"atom_symbol":"H","shell":"1s","component":"","name":"1s"},
        \\    {"index":1,"atom_index":1,"atom_symbol":"H","shell":"1s","component":"","name":"1s"}
        \\  ],
        \\  "S": [[1.0, 0.659], [0.659, 1.0]],
        \\  "T": [[0.76, 0.24], [0.24, 0.76]],
        \\  "V_nuc": [[-1.88, -1.19], [-1.19, -1.88]],
        \\  "eri": [[[[0.7, 0.1], [0.1, 0.2]], [[0.1, 0.2], [0.2, 0.1]]],
        \\          [[[0.1, 0.2], [0.2, 0.1]], [[0.2, 0.1], [0.1, 0.7]]]],
        \\  "scf": {"method":"RHF","converged":true,"energy":-1.117,
        \\          "density":[[1.0,0.5],[0.5,1.0]],
        \\          "mo_energies":[-0.59, 0.70]}
        \\}
    ;

    var parsed = try parseTestCase(std.testing.allocator, text);
    defer parsed.deinit();

    const c = parsed.value;
    try std.testing.expectEqualStrings("test", c.case);
    try std.testing.expectEqualStrings("sto-3g", c.basis);
    try std.testing.expectEqual(@as(usize, 2), c.nao);
    try std.testing.expectEqual(@as(usize, 2), c.molecule.atoms.len);
    try std.testing.expectEqual(@as(usize, 2), c.ao_labels.len);
    try std.testing.expectEqualStrings("H", c.molecule.atoms[0].symbol);
    try std.testing.expectEqualStrings("1s", c.ao_labels[0].name);
    try std.testing.expectApproxEqAbs(@as(f64, 0.74), c.molecule.atoms[1].coord[2], 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 0.659), c.S[0][1], 1e-12);
    try std.testing.expect(c.eri != null);
    try std.testing.expect(c.scf != null);
    try validateShapes(c);
}

test "toBohr rejects unsupported coordinate units" {
    try std.testing.expectError(error.UnsupportedUnit, toBohr(.{ 0.0, 0.0, 0.0 }, "nanometer"));
}

test "atomicNumberForSymbol rejects unsupported element symbols" {
    try std.testing.expectError(error.UnsupportedElement, atomicNumberForSymbol("Uue"));
}

test "validateShapes rejects malformed matrix dimensions" {
    var parsed = try readFixture("testdata/reference/malformed/shape.json");
    defer parsed.deinit();

    try std.testing.expectError(error.ShapeMismatch, validateShapes(parsed.value));
}

test "validateShapes rejects atom count mismatches" {
    const text =
        \\{
        \\  "case": "bad-atom-count",
        \\  "molecule": {
        \\    "atoms": [["H", [0.0, 0.0, 0.0]]],
        \\    "unit": "bohr", "charge": 0, "spin": 0
        \\  },
        \\  "basis": "sto-3g",
        \\  "nao": 1, "natm": 2, "nelectron": 1,
        \\  "nuclear_repulsion": 0.0,
        \\  "pyscf_version": "test",
        \\  "ao_labels": [
        \\    {"index":0,"atom_index":0,"atom_symbol":"H","shell":"1s","component":"","name":"1s"}
        \\  ],
        \\  "S": [[1.0]],
        \\  "T": [[0.5]],
        \\  "V_nuc": [[-1.0]]
        \\}
    ;

    var parsed = try parseTestCase(std.testing.allocator, text);
    defer parsed.deinit();

    try std.testing.expectError(error.ShapeMismatch, validateShapes(parsed.value));
}

test "validateShapes rejects AO label atom symbol mismatches" {
    const text =
        \\{
        \\  "case": "bad-ao-symbol",
        \\  "molecule": {
        \\    "atoms": [["H", [0.0, 0.0, 0.0]]],
        \\    "unit": "bohr", "charge": 0, "spin": 0
        \\  },
        \\  "basis": "sto-3g",
        \\  "nao": 1, "natm": 1, "nelectron": 1,
        \\  "nuclear_repulsion": 0.0,
        \\  "pyscf_version": "test",
        \\  "ao_labels": [
        \\    {"index":0,"atom_index":0,"atom_symbol":"He","shell":"1s","component":"","name":"1s"}
        \\  ],
        \\  "S": [[1.0]],
        \\  "T": [[0.5]],
        \\  "V_nuc": [[-1.0]]
        \\}
    ;

    var parsed = try parseTestCase(std.testing.allocator, text);
    defer parsed.deinit();

    try std.testing.expectError(error.ShapeMismatch, validateShapes(parsed.value));
}

test "readTestCaseFile reads a generated PySCF fixture" {
    var parsed = try readFixture("testdata/reference/cases/h2_sto-3g.json");
    defer parsed.deinit();

    const c = parsed.value;
    try std.testing.expectEqualStrings("h2_sto-3g", c.case);
    try std.testing.expectEqual(@as(usize, 2), c.nao);
    try std.testing.expectApproxEqAbs(@as(f64, -1.1175058845763317), c.scf.?.energy, 1e-7);
    try validateShapes(c);
}

test "h2_sto-3g individual one-electron integral golden values" {
    var parsed = try readFixture("testdata/reference/cases/h2_sto-3g.json");
    defer parsed.deinit();

    const h2 = parsed.value;
    try std.testing.expectEqual(@as(usize, 2), h2.nao);

    try expectIntegral(0.9999999999999999, h2.S[0][0]);
    try expectIntegral(0.6780519271172516, h2.S[0][1]);
    try expectIntegral(0.9999999999999999, h2.S[1][1]);

    try expectIntegral(0.7600318799223883, h2.T[0][0]);
    try expectIntegral(0.2538519186169455, h2.T[0][1]);
    try expectIntegral(0.7600318799223883, h2.T[1][1]);

    try expectIntegral(-1.8993527053135226, h2.V_nuc[0][0]);
    try expectIntegral(-1.2460926621761292, h2.V_nuc[0][1]);
    try expectIntegral(-1.899352705313523, h2.V_nuc[1][1]);
}

test "h2_sto-3g AO labels map matrix indexes to atoms and orbitals" {
    var parsed = try readFixture("testdata/reference/cases/h2_sto-3g.json");
    defer parsed.deinit();

    const labels = parsed.value.ao_labels;
    try std.testing.expectEqual(@as(usize, 2), labels.len);

    try std.testing.expectEqual(@as(usize, 0), labels[0].index);
    try std.testing.expectEqual(@as(usize, 0), labels[0].atom_index);
    try std.testing.expectEqualStrings("H", labels[0].atom_symbol);
    try std.testing.expectEqualStrings("1s", labels[0].shell);
    try std.testing.expectEqualStrings("", labels[0].component);
    try std.testing.expectEqualStrings("1s", labels[0].name);

    try std.testing.expectEqual(@as(usize, 1), labels[1].index);
    try std.testing.expectEqual(@as(usize, 1), labels[1].atom_index);
    try std.testing.expectEqualStrings("H", labels[1].atom_symbol);
    try std.testing.expectEqualStrings("1s", labels[1].name);
}

test "h2_sto-3g individual electron-repulsion integral golden values" {
    var parsed = try readFixture("testdata/reference/cases/h2_sto-3g.json");
    defer parsed.deinit();

    const eri = parsed.value.eri orelse return error.TestUnexpectedResult;

    try expectIntegral(0.7746059442114875, eri[0][0][0][0]);
    try expectIntegral(0.46052074615887156, eri[0][0][0][1]);
    try expectIntegral(0.5804723342277581, eri[0][0][1][1]);
    try expectIntegral(0.3163483284574559, eri[0][1][0][1]);
    try expectIntegral(0.46052074615887184, eri[0][1][1][1]);
    try expectIntegral(0.7746059442114875, eri[1][1][1][1]);
}

test "he_sto-3g individual one-center integral golden values" {
    var parsed = try readFixture("testdata/reference/cases/he_sto-3g.json");
    defer parsed.deinit();

    const he = parsed.value;
    const eri = he.eri orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(@as(usize, 1), he.nao);
    try expectIntegral(0.9999999999999998, he.S[0][0]);
    try expectIntegral(1.4117631711227245, he.T[0][0]);
    try expectIntegral(-3.3435116194404526, he.V_nuc[0][0]);
    try expectIntegral(1.0557129400212608, eri[0][0][0][0]);
}

test "h2o_sto-3g individual p-shell integral golden values" {
    var parsed = try readFixture("testdata/reference/cases/h2o_sto-3g.json");
    defer parsed.deinit();

    const h2o = parsed.value;
    const eri = h2o.eri orelse return error.TestUnexpectedResult;

    try std.testing.expectEqual(@as(usize, 7), h2o.nao);

    try expectIntegral(0.23670392057272616, h2o.S[0][1]);
    try expectIntegral(0.2926885447579104, h2o.S[3][5]);
    try expectIntegral(-0.29268854475793216, h2o.S[3][6]);
    try expectIntegral(-0.24551189516781657, h2o.S[4][5]);

    try expectIntegral(2.5287312263164647, h2o.T[3][3]);
    try expectIntegral(0.1992358680484053, h2o.T[3][5]);
    try expectIntegral(-0.1992358680484209, h2o.T[3][6]);

    try expectIntegral(-10.055205827624235, h2o.V_nuc[4][4]);
    try expectIntegral(1.8255356137889254, h2o.V_nuc[4][5]);
    try expectIntegral(1.8255356137887502, h2o.V_nuc[4][6]);

    try expectIntegral(4.785065751815713, eri[0][0][0][0]);
    try expectIntegral(0.8801590896471139, eri[3][3][3][3]);
    try expectIntegral(0.506640287988893, eri[3][3][5][5]);
    try expectIntegral(0.2375768099581293, eri[3][5][5][5]);
    try expectIntegral(0.7746059442114875, eri[5][5][5][5]);
}

test "h2o_sto-3g AO labels include oxygen p components in PySCF order" {
    var parsed = try readFixture("testdata/reference/cases/h2o_sto-3g.json");
    defer parsed.deinit();

    const labels = parsed.value.ao_labels;
    try std.testing.expectEqual(@as(usize, 7), labels.len);

    try std.testing.expectEqual(@as(usize, 0), labels[0].atom_index);
    try std.testing.expectEqualStrings("O", labels[0].atom_symbol);
    try std.testing.expectEqualStrings("1s", labels[0].name);

    try std.testing.expectEqual(@as(usize, 0), labels[1].atom_index);
    try std.testing.expectEqualStrings("O", labels[1].atom_symbol);
    try std.testing.expectEqualStrings("2s", labels[1].name);

    try std.testing.expectEqual(@as(usize, 0), labels[2].atom_index);
    try std.testing.expectEqualStrings("O", labels[2].atom_symbol);
    try std.testing.expectEqualStrings("2p", labels[2].shell);
    try std.testing.expectEqualStrings("x", labels[2].component);
    try std.testing.expectEqualStrings("2px", labels[2].name);

    try std.testing.expectEqualStrings("y", labels[3].component);
    try std.testing.expectEqualStrings("2py", labels[3].name);
    try std.testing.expectEqualStrings("z", labels[4].component);
    try std.testing.expectEqualStrings("2pz", labels[4].name);

    try std.testing.expectEqual(@as(usize, 1), labels[5].atom_index);
    try std.testing.expectEqualStrings("H", labels[5].atom_symbol);
    try std.testing.expectEqualStrings("1s", labels[5].name);
    try std.testing.expectEqual(@as(usize, 2), labels[6].atom_index);
    try std.testing.expectEqualStrings("H", labels[6].atom_symbol);
    try std.testing.expectEqualStrings("1s", labels[6].name);
}

test "readTestCasesDir loads all generated PySCF fixtures" {
    var cases = try readTestCasesDir(
        std.testing.io,
        std.testing.allocator,
        "testdata/reference/cases",
    );
    defer cases.deinit(std.testing.allocator);

    try std.testing.expect(cases.items.len >= 1);

    const h2 = cases.get("h2_sto-3g") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 2), h2.nao);
    try std.testing.expectApproxEqAbs(@as(f64, 0.742961700998514), h2.nuclear_repulsion, 1e-9);
    try validateShapes(h2.*);
}
